# Muzayede Faz 6: veritabaninda tek tablosu olan 172 ressama 3'er ek tablo
# arandi (ayni ressamdan birden fazla tablo artik ressam_id/tablo_id
# ayrimi sayesinde destekleniyor, bkz. veri/muzayede_uret.py). Uc turda
# calisti: ilk tur 172 ressamdan 48'i tamamlandi (oturum limitine
# takildi), retry turu kalan 124'ten 110'unu tamamladi (kullanici
# durdurdu, 14 ressam hic denenmedi), son kucuk tur kalan 14'ten 1800
# oncesi 2'sini (Watteau, Wright of Derby - filtreye takilacaklardi)
# atlayip 12'sini tamamladi. Toplam 170/172 ressam islendi, 199 aday
# tablo bulundu.
#
# 1800 oncesi dogumlu ressamlarin ek tablolari kullanici tercihiyle
# filtrelendi ("1800ler ve sonrasi agirlikli olsun, oncesinde Mona Lisa
# gibi en unluler disinda cok olmasin"): sadece Tiziano, Rubens,
# Botticelli, Goya, Hokusai, Delacroix icin ek tablo eklendi; digerlerinin
# (18 ressam, 34 tablo) bulunan ek tablolari bu turda EKLENMEDI (mevcut
# tek tablolari degismedi, sadece yeni tablo eklenmedi).
#
# Alan sirasi ana DATA ile ayni: ressam_id, isim, dogum_olum, ulke, akim,
# risk_seviyesi, tablo_adi, tablo_yili, gorsel_url, fiyat_usd, satis_yili,
# muzayede_evi, kaynak_url

